    # Defect for first 3 rounds
    if round_num <= 3:
        return False

    # Compute own recent cooperation rate over last 5 rounds (only own actions)
    recent = my_history[-5:] if len(my_history) >= 5 else my_history
    if recent:
        own_coop_rate = sum(recent) / len(recent)
    else:
        own_coop_rate = 0.5

    # Adjust threshold: more cooperative agents are more trusting
    if own_coop_rate > 0.6:
        threshold = 0.2
    elif own_coop_rate < 0.2:
        threshold = 0.8
    else:
        threshold = 0.5

    return recipient_reputation > threshold

